    "description": {
      "en": "S-IE-013 · ANC TWS earbuds. 13 mm · ANC + ENC. Explore this audio platform for your next branded product. Review fit, sound and finish with a sample before agreeing on production.",
      "fr": "S-IE-013 · ANC Écouteurs TWS. 13 mm · ANC + ENC. Explorez cette plateforme audio pour votre prochain produit de marque. Évaluez le confort, le son et la finition sur échantillon avant de convenir de la production.",
      "es": "S-IE-013 · ANC Auriculares TWS. 13 mm · ANC + ENC. Explora esta plataforma de audio para tu próximo producto de marca. Evalúa ajuste, sonido y acabado con una muestra antes de acordar la producción.",
      "pt": "S-IE-013 · ANC Fones TWS. 13 mm · ANC + ENC. Explore esta plataforma de áudio para o seu próximo produto de marca. Avalie ajuste, som e acabamento em uma amostra antes de acordar a produção.",
      "ru": "S-IE-013 · ANC Наушники TWS. 13 mm · ANC + ENC. Рассмотрите эту аудиоплатформу для следующего продукта вашего бренда. Оцените посадку, звук и отделку по образцу до согласования производства.",
      "ar": "S-IE-013 · ANC سماعات TWS. 13 mm · ANC + ENC. استكشف هذه المنصة الصوتية لمنتج علامتك القادم. راجع الملاءمة والصوت والتشطيب باستخدام عينة قبل الاتفاق على الإنتاج.",
      "zh": "S-IE-013 · ANC TWS 真无线耳机. 13 mm · ANC + ENC. 从这款音频平台出发，规划下一款品牌产品。量产方案确定前，通过样品评估佩戴、声音与表面工艺。"
    },
