      "es": "S-OH-022 · Auriculares inalámbricos de diadema. 40 mm · Diseño plegable · Reproducción desde tarjeta. Explora esta plataforma de audio para tu próximo producto de marca. Evalúa ajuste, sonido y acabado con una muestra antes de acordar la producción.",
