      "ru": "S-OH-037 · Беспроводные полноразмерные наушники. 40 mm · Воспроизведение с карты · Подсветка RGB. Рассмотрите эту аудиоплатформу для следующего продукта вашего бренда. Оцените посадку, звук и отделку по образцу до согласования производства.",
      "ar": "S-OH-037 · سماعات لاسلكية حول الأذن. 40 mm · تشغيل من بطاقة ذاكرة · إضاءة RGB. استكشف هذه المنصة الصوتية لمنتج علامتك القادم. راجع الملاءمة والصوت والتشطيب باستخدام عينة قبل الاتفاق على الإنتاج.",
      "zh": "S-OH-037 · 无线头戴式耳机. 40 mm · 存储卡播放 · RGB 灯效. 从这款音频平台出发，规划下一款品牌产品。量产方案确定前，通过样品评估佩戴、声音与表面工艺。"
