      "es": "S-OH-041 · Auriculares inalámbricos de diadema. 40 mm · Diseño plegable · Reproducción desde tarjeta. Explora esta plataforma de audio para tu próximo producto de marca. Evalúa ajuste, sonido y acabado con una muestra antes de acordar la producción.",
      "pt": "S-OH-041 · Fone circum-aural sem fio. 40 mm · Design dobrável · Reprodução por cartão. Explore esta plataforma de áudio para o seu próximo produto de marca. Avalie ajuste, som e acabamento em uma amostra antes de acordar a produção.",
